<?php $page='messages';require __DIR__.'/_head.php';if(isset($_GET['read'])){check_csrf();db()->prepare("UPDATE messages SET status='read' WHERE id=?")->execute([(int)$_GET['read']]);header('Location:messages.php');exit;}if(isset($_GET['delete'])){check_csrf();db()->prepare('DELETE FROM messages WHERE id=?')->execute([(int)$_GET['delete']]);header('Location:messages.php');exit;}$rows=db()->query('SELECT * FROM messages ORDER BY id DESC')->fetchAll();?><div class="topbar"><h1>Contact Messages</h1></div><div class="panel"><table class="table"><tr><th>Name</th><th>Contact</th><th>Subject</th><th>Message</th><th>Status</th><th>Date</th><th></th></tr><?php foreach($rows as $m):?><tr><td><b><?=e($m['name'])?></b></td><td><?=e($m['email'])?><br><?=e($m['phone'])?></td><td><?=e($m['subject'])?></td><td style="max-width:360px;white-space:pre-wrap"><?=e($m['message'])?></td><td><?=e($m['status'])?></td><td><?=e($m['created_at'])?></td><td class="actions"><?php if($m['status']==='new'):?><a class="btn" href="?read=<?=$m['id']?>&csrf=<?=e(csrf())?>">Mark read</a><?php endif;?><a class="btn danger" onclick="return confirm('Delete message?')" href="?delete=<?=$m['id']?>&csrf=<?=e(csrf())?>">Delete</a></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/_foot.php';
